// =============================================================================
// This file was generated by Claude, just for fun, to compare
// hash_map::HashMap against the standard associative containers:
//   - std::unordered_map        (hash table, unique keys)
//   - std::unordered_multimap   (hash table, duplicate keys allowed)
//   - std::multimap             (red-black tree, duplicate keys allowed)
// Not scientifically rigorous :)
//
// Idea: HashMap stores nodes in a flat array of cache lines, and the key only
// selects a "column" (hash & 63). A lookup walks that column through all chunks.
// So:
//   + while the table is small (1-2 chunks), everything stays in cache, there
//     is no per-node allocation and no pointer chasing -> should be fast;
//   - once there are many chunks, a lookup becomes O(N / 512) memory hops with
//     a 4 KB stride -> should be much slower than the std containers.
//
// Note: my insert() does not look for duplicates, so the multimaps are the
// fairer comparison for insertion (emplace() on them does not reject keys).
//
// Build in Release (-O2), otherwise the numbers mean nothing.
// =============================================================================

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <map>
#include <numeric>
#include <random>
#include <unordered_map>
#include <vector>

#include "hash_map/hash_map.hpp"

using MyMap = hash_map::HashMap<int, int>;
using UMap = std::unordered_map<int, int>;
using UMultiMap = std::unordered_multimap<int, int>;
using MultiMap = std::multimap<int, int>;

using clk = std::chrono::steady_clock;

struct Result {
  double ms;
  std::uint64_t checksum;
};

// ---- helpers -----------------------------------------------------------------

// Prevents the compiler from discarding computations whose result is unused.
inline void keep(std::uint64_t v) { asm volatile("" : : "r"(v) : "memory"); }

inline double elapsed_ms(clk::time_point t0) {
  return std::chrono::duration<double, std::milli>(clk::now() - t0).count();
}

// The only places where the APIs differ (multimaps have no at()/operator[]).
inline void put(MyMap &m, int k, int v) { m.insert(k, v); }
template <class M> inline void put(M &m, int k, int v) { m.emplace(k, v); }

inline int get(const MyMap &m, int k) { return m.at(k); }
template <class M> inline int get(const M &m, int k) {
  return m.find(k)->second;
}

// ---- parameters --------------------------------------------------------------

constexpr int SMALL_N = 256;          // fits into a couple of lines per column
constexpr int HOT_REPS = 2'000'000;   // lookups on the small map
constexpr int BUILD_N = 128;          // map size for "build from scratch"
constexpr int BUILD_REPS = 20'000;    // how many times we rebuild it
constexpr int LARGE_N = 50'000;       // the "large" map
constexpr int LARGE_MISS = 20'000;    // misses on the large map
constexpr int STRIDE_N = 10'000;      // keys that are multiples of 64
constexpr int STRIDE_QUERIES = 2'000;

// ---- favorable scenarios -----------------------------------------------------

// 1. Small map, many successful lookups (everything in L1, no allocations).
template <class Map> Result s_small_hit() {
  Map m;
  for (int i = 0; i < SMALL_N; ++i)
    put(m, i, i * 2);

  std::uint64_t sum = 0;
  auto t0 = clk::now();
  for (int i = 0; i < HOT_REPS; ++i)
    sum += static_cast<std::uint64_t>(get(m, (i * 7) & (SMALL_N - 1)));
  double ms = elapsed_ms(t0);
  keep(sum);
  return {ms, sum};
}

// 2. Small map, lookups of absent keys.
template <class Map> Result s_small_miss() {
  Map m;
  for (int i = 0; i < SMALL_N; ++i)
    put(m, i, i * 2);

  std::uint64_t sum = 0;
  auto t0 = clk::now();
  for (int i = 0; i < HOT_REPS; ++i)
    sum += m.contains(SMALL_N + ((i * 7) & (SMALL_N - 1))) ? 1 : 0;
  double ms = elapsed_ms(t0);
  keep(sum);
  return {ms, sum};
}

// 3. Build a small map from scratch many times (one allocation for yours vs.
//    128 node allocations for the node-based std containers).
template <class Map> Result s_build_small() {
  std::uint64_t sum = 0;
  auto t0 = clk::now();
  for (int r = 0; r < BUILD_REPS; ++r) {
    Map m;
    for (int i = 0; i < BUILD_N; ++i)
      put(m, i, i + r);
    sum += static_cast<std::uint64_t>(get(m, BUILD_N / 2));
  }
  double ms = elapsed_ms(t0);
  keep(sum);
  return {ms, sum};
}

// ---- unfavorable scenarios ---------------------------------------------------

// 4. Inserting a large number of elements.
template <class Map> Result s_large_insert() {
  Map m;
  auto t0 = clk::now();
  for (int i = 0; i < LARGE_N; ++i)
    put(m, i, i * 2);
  double ms = elapsed_ms(t0);
  return {ms, static_cast<std::uint64_t>(m.size())};
}

// 5. Random successful lookups on the large map.
template <class Map> Result s_large_hit() {
  Map m;
  for (int i = 0; i < LARGE_N; ++i)
    put(m, i, i * 2);

  std::vector<int> keys(LARGE_N);
  std::iota(keys.begin(), keys.end(), 0);
  std::mt19937 rng(42);
  std::shuffle(keys.begin(), keys.end(), rng);

  std::uint64_t sum = 0;
  auto t0 = clk::now();
  for (int k : keys)
    sum += static_cast<std::uint64_t>(get(m, k));
  double ms = elapsed_ms(t0);
  keep(sum);
  return {ms, sum};
}

// 6. Misses on the large map: every chunk of the column has to be scanned.
template <class Map> Result s_large_miss() {
  Map m;
  for (int i = 0; i < LARGE_N; ++i)
    put(m, i, i * 2);

  std::uint64_t sum = 0;
  auto t0 = clk::now();
  for (int i = 0; i < LARGE_MISS; ++i)
    sum += m.contains(LARGE_N + i) ? 1 : 0;
  double ms = elapsed_ms(t0);
  keep(sum);
  return {ms, sum};
}

// 7. Pathological keys: all multiples of 64, so hash & 63 == 0 for every key.
//    Everything lands in one column while the other 63 stay empty.
template <class Map> Result s_stride64() {
  std::vector<int> idx(STRIDE_N);
  std::iota(idx.begin(), idx.end(), 0);
  std::mt19937 rng(7);
  std::shuffle(idx.begin(), idx.end(), rng);

  Map m;
  std::uint64_t sum = 0;
  auto t0 = clk::now();
  for (int i = 0; i < STRIDE_N; ++i)
    put(m, i * 64, i);
  for (int q = 0; q < STRIDE_QUERIES; ++q)
    sum += static_cast<std::uint64_t>(get(m, idx[q] * 64));
  double ms = elapsed_ms(t0);
  keep(sum);
  return {ms, sum};
}

// ---- output ------------------------------------------------------------------

using Fn = Result (*)();

void compare(const char *name, Fn mine, Fn umap, Fn umulti, Fn multi) {
  const Result r[4] = {mine(), umap(), umulti(), multi()};
  static const char *const names[4] = {"mine", "unordered_map",
                                       "unordered_multimap", "multimap"};

  int best = 0;
  bool mismatch = false;
  for (int i = 0; i < 4; ++i) {
    if (r[i].ms < r[best].ms)
      best = i;
    if (r[i].checksum != r[0].checksum)
      mismatch = true;
  }

  std::printf("%-34s %10.2f %14.2f %19.2f %10.2f   %s%s\n", name, r[0].ms,
              r[1].ms, r[2].ms, r[3].ms, names[best],
              mismatch ? "   [!] RESULTS DIFFER" : "");
}

#define RUN(label, scenario)                                                   \
  compare(label, scenario<MyMap>, scenario<UMap>, scenario<UMultiMap>,        \
          scenario<MultiMap>)

int main() {
  std::printf("cache_line_size = %zu, node_capacity = %zu\n\n",
              hash_map::cache_line_size, MyMap::node_capacity);
  std::printf("%-34s %10s %14s %19s %10s   %s\n", "scenario (ms)", "mine",
              "unordered_map", "unordered_multimap", "multimap", "fastest");
  std::printf("------------------------------------------------------------"
              "------------------------------------------------------\n");

  std::printf("# favorable for my map\n");
  RUN("small: lookup (hit)", s_small_hit);
  RUN("small: lookup (miss)", s_small_miss);
  RUN("small: build from scratch x20000", s_build_small);

  std::printf("# unfavorable\n");
  RUN("large 50k: insert", s_large_insert);
  RUN("large 50k: lookup (hit)", s_large_hit);
  RUN("large 50k: lookup (miss)", s_large_miss);
  RUN("keys multiple of 64 (1 column)", s_stride64);

  return 0;
}
